package com.freshmart.catalog;
import com.freshmart.common.*;
import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
import java.math.BigInteger;import java.time.*;import java.util.*;import java.util.stream.Collectors;
@Service @Transactional(readOnly=true)
public class CatalogService {
 private final CatalogMapper mapper;private final Clock clock;private final int nearDays,discountBps;
 public CatalogService(CatalogMapper mapper,Clock clock,@Value("${app.near-expiry-days:3}")int nearDays,@Value("${app.near-expiry-discount-basis-points:9000}")int discountBps){this.mapper=mapper;this.clock=clock;this.nearDays=nearDays;this.discountBps=discountBps;if(nearDays<1||discountBps<1||discountBps>10000)throw new IllegalStateException("Invalid catalog freshness configuration");}
 public List<CategoryView> categories(){return mapper.categories().stream().map(c->new CategoryView(c.categoryId(),c.code(),c.name(),c.shortName(),c.imageUrl(),c.sortOrder())).toList();}
 public PageResult<ProductView> products(int page,int size,String category,String keyword,boolean nearExpiry,String sort){validatePaging(page,size);if(category!=null&&!category.matches("[A-Za-z0-9_-]{1,64}"))throw ApiException.invalid("分类ID格式不合法");if(keyword!=null&&(keyword.isBlank()||keyword.length()>100))throw ApiException.invalid("关键词长度不合法");if(!Set.of("RECOMMENDED","PRICE_ASC","PRICE_DESC").contains(sort))throw ApiException.invalid("排序参数不合法");Instant now=clock.instant(),nearAt=now.plus(Duration.ofDays(nearDays));long total=mapper.count(category,keyword,nearExpiry,now,nearAt);var rows=mapper.products(category,keyword,nearExpiry,sort,now,nearAt,discountBps,size,((long)page-1)*size);return new PageResult<>(page,size,total,views(rows,now));}
 public ProductView product(String id){ProductRow p=mapper.product(id);if(p==null)throw ApiException.notFound();var products=views(List.of(p),clock.instant());if(products.isEmpty())throw ApiException.notFound();return products.getFirst();}
 public HomeView home(){return new HomeView(List.of(),categories(),products(1,8,null,null,true,"RECOMMENDED").items(),products(1,12,null,null,false,"RECOMMENDED").items(),clock.instant().toString());}
 public PageResult<Map<String,Object>> reviews(String id,int page,int size){validatePaging(page,size);product(id);return new PageResult<>(page,size,0,List.of());}
 private void validatePaging(int page,int size){if(page<1||size<1||size>100)throw ApiException.invalid("page从1开始，size为1到100");}
 private List<ProductView> views(List<ProductRow> products,Instant now){if(products.isEmpty())return List.of();List<SkuRow> skus=mapper.skus(products.stream().map(ProductRow::productId).toList());if(skus.isEmpty())return List.of();Map<String,List<CatalogBatchRow>> batches=mapper.availableBatches(skus.stream().map(SkuRow::skuId).toList(),now).stream().collect(Collectors.groupingBy(CatalogBatchRow::skuId));Map<String,List<SkuView>> grouped=new HashMap<>();for(SkuRow sku:skus)grouped.computeIfAbsent(sku.productId(),k->new ArrayList<>()).add(skuView(sku,batches.getOrDefault(sku.skuId(),List.of()),now));List<ProductView>result=new ArrayList<>();for(ProductRow p:products){List<SkuView> list=grouped.getOrDefault(p.productId(),List.of());if(list.isEmpty())continue;SkuView first=list.stream().min(Comparator.comparingLong(SkuView::salePrice).thenComparing(SkuView::skuId)).orElseThrow();boolean near=list.stream().anyMatch(SkuView::nearExpiry);String stock=list.stream().anyMatch(s->s.stockStatus().equals("IN_STOCK"))?"IN_STOCK":list.stream().anyMatch(s->s.stockStatus().equals("LOW"))?"LOW":"SOLD_OUT";SkuView earliest=list.stream().filter(s->s.shelfLifeRemainingDays()!=null).min(Comparator.comparingLong(SkuView::shelfLifeRemainingDays)).orElse(null);result.add(new ProductView(p.productId(),p.spuCode(),p.categoryId(),p.name(),p.description(),p.origin(),p.storage(),p.imageUrl(),first.price(),first.memberPrice(),first.salePrice(),first.priceMode(),first.unitLabel(),stock,near,List.copyOf(list),p.version(),earliest==null?null:earliest.arrivedAt(),earliest==null?null:near?"NEAR_EXPIRY":"NORMAL",earliest==null?null:earliest.shelfLifeRemainingDays()));}return List.copyOf(result);}
 private SkuView skuView(SkuRow sku,List<CatalogBatchRow>batches,Instant now){long available=batches.stream().mapToLong(CatalogBatchRow::available).reduce(0,Math::addExact);CatalogBatchRow candidate=batches.isEmpty()?null:batches.getFirst();boolean near=candidate!=null&&!candidate.expiresAt().isAfter(now.plus(Duration.ofDays(nearDays)));long discount=BigInteger.valueOf(sku.price()).multiply(BigInteger.valueOf(discountBps)).add(BigInteger.valueOf(5000)).divide(BigInteger.valueOf(10000)).longValueExact();long sale=near?Math.min(sku.memberPrice(),discount):sku.memberPrice();long threshold="GRAM".equals(sku.baseUnit())?5000:5;String stock=available==0?"SOLD_OUT":available<=threshold?"LOW":"IN_STOCK";return new SkuView(sku.skuId(),sku.skuCode(),sku.name(),sku.unitLabel(),sku.baseUnit(),sku.priceMode(),sku.priceUnitGram(),sku.price(),sku.memberPrice(),sale,stock,near,sku.imageUrl(),sku.version(),candidate==null?null:candidate.receivedAt().toString(),candidate==null?null:near?"NEAR_EXPIRY":"NORMAL",candidate==null?null:Duration.between(now,candidate.expiresAt()).toDays());}
 public record CategoryView(String categoryId,String code,String name,String shortName,String imageUrl,int sortOrder){}
 public record SkuView(String skuId,String skuCode,String name,String unitLabel,String baseUnit,String priceMode,Long priceUnitGram,long price,long memberPrice,long salePrice,String stockStatus,boolean nearExpiry,String imageUrl,long version,String arrivedAt,String freshness,Long shelfLifeRemainingDays){}
 public record ProductView(String productId,String spuCode,String categoryId,String name,String description,String origin,String storage,String imageUrl,long price,long memberPrice,long salePrice,String priceMode,String unitLabel,String stockStatus,boolean nearExpiry,List<SkuView>skus,long version,String arrivedAt,String freshness,Long shelfLifeRemainingDays){}
 public record HomeView(List<Object>banners,List<CategoryView>categories,List<ProductView>nearExpiryProducts,List<ProductView>recommendedProducts,String generatedAt){}
}
